using System.Net;
using System.Text.Json;

namespace VirtualMonitorsUniverse.Server;

/// <summary>
/// Centralized HTML/CSS/JavaScript renderer for the built-in VMU web client.
/// The UI is deliberately dependency-free and every primary action is available
/// to both mouse/keyboard and touch users.
/// </summary>
internal static class WebUiRenderer
{
    public static string Shell(string title, string body, string navigation, string bodyClass = "", string extraNav = "")
    {
        return "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>" + WebUtility.HtmlEncode(title) + " - VMU</title><style>" + Css + "</style></head><body class=\"" + bodyClass + "\"><div id=\"topHotspot\" class=\"topHotspot\"></div><nav id=\"topNav\"><div class=\"navwrap\"><button id=\"navButton\" class=\"gear iconButton\" type=\"button\" aria-label=\"Open navigation\">▣</button><div id=\"navMenu\" class=\"navmenu\"><a href=\"/\">Status</a><a href=\"/monitors\">Monitors</a><a href=\"/arrangement\">Arrangement</a><a href=\"/settings\">Settings</a><a href=\"/log\">View Log</a></div></div><div id=\"monitorNavHost\" class=\"monitorNavHost\">" + navigation + "</div><div class=\"navSpacer\"></div>" + extraNav + "</nav>" + body + ConnectionOverlay + CommonJs + "</body></html>";
    }

    public static string MonitorNavigation(IEnumerable<MonitorSnapshot> monitors, bool vmuRunning)
    {
        if (!vmuRunning) return string.Empty;
        return string.Join("", monitors.Where(x => x.Connected && !x.Health.IsError).Select(m =>
        {
            var name = Uri.EscapeDataString(m.Configuration.Name);
            var title = WebUtility.HtmlEncode(m.Configuration.Title);
            var avatar = m.Configuration.AvatarKind.Equals("custom", StringComparison.OrdinalIgnoreCase)
                ? $"<img class=\"navAvatar\" src=\"/api/monitors/{name}/avatar?t={DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}\" alt=\"\">"
                : $"<span class=\"navAvatarEmoji\">{MonitorAvatarService.GetEmoji(m.Configuration.AvatarKind, m.Configuration.AvatarValue)}</span>";
            return $"""
<div class="monitorNavWrap" data-monitor="{WebUtility.HtmlEncode(m.Configuration.Name)}">
  <a class="monitorNav" href="/monitor/{name}">{avatar}<b>{title}</b></a>
  <div class="monitorMenu">
    <label><input type="checkbox" checked disabled> Clipboard</label>
    <label><input type="checkbox" checked disabled> Mouse</label>
    <label><input type="checkbox" checked disabled> Keyboard</label>
    <hr>
    <a href="/monitors/{name}">Properties</a>
  </div>
</div>
""";
        }));
    }

