</div>
<script>
const q=i=>document.getElementById(i),pct=v=>v==null?'—':v.toFixed(1)+' %',rate=v=>v==null?'—':v<1048576?(v/1024).toFixed(1)+' KB/s':(v/1048576).toFixed(1)+' MB/s';
async function st(){try{const s=await fetch('/api/status',{cache:'no-store'}).then(r=>r.json());q('version').textContent='Version '+s.version;q('services').innerHTML=s.services.map(x=>'<div class="service"><span class="dot '+(x.running?'on':'off')+'"></span><span>'+x.name+'</span><b>'+(x.running?'Running':'Stopped')+'</b></div>').join('');q('installed').textContent=s.monitors.installed;q('connected').textContent=s.monitors.connected;q('remote').textContent=s.remote.enabled?'Enabled':'Disabled';q('clients').textContent=s.remote.clients;['github','documentation','guide','bugs'].forEach(k=>{q(k).href=s.links[k];q(k).target='_blank'});}catch{}}
async function rs(){if(document.hidden)return;try{const r=await fetch('/api/resources',{cache:'no-store'}).then(x=>x.json());q('cpuS').textContent=pct(r.systemCpu);q('cpuV').textContent=pct(r.vmuCpu);q('gpuS').textContent=pct(r.systemGpu);q('gpuV').textContent=pct(r.vmuGpu);q('ramS').textContent=pct(r.systemRam);q('ramV').textContent=r.vmuRamBytes==null?'—':(r.vmuRamBytes/1048576).toFixed(0)+' MB';q('netS').textContent=rate(r.systemNetBytesPerSecond);q('netV').textContent=rate(r.vmuNetBytesPerSecond);}catch{}}
st();rs();setInterval(st,2000);setInterval(rs,2000);
