    public static string SettingsBody() => """
<div class="page settingsPage"><h1>Settings</h1><div id="error" class="error"></div><form id="form">
<fieldset><legend>Services</legend><table class="settingsTable"><tr><th>Service</th><th>Interface</th><th>Port</th></tr>
<tr><td>VMU Server</td><td><select id="vmuInterface" class="interfaceInput"><option value="localhost">localhost</option><option value="any">All Interfaces</option></select></td><td><input id="vmuPort" class="portInput" type="number"></td></tr>
<tr><td>Web Server</td><td><select id="webInterface" class="interfaceInput"><option value="localhost">localhost</option><option value="any">All Interfaces</option></select></td><td><input id="webPort" class="portInput" type="number"></td></tr>
<tr><td>Web Socket</td><td><select id="socketInterface" class="interfaceInput"><option value="localhost">localhost</option><option value="any">All Interfaces</option></select></td><td><input id="socketPort" class="portInput" type="number"></td></tr></table></fieldset>
<fieldset><legend>Web and Logging</legend><div class="formgrid"><label>Log Retention</label><div><input id="retention" class="smallNumber" type="number"> days</div><label>Monitor Preview</label><select id="preview" class="mediumInput"><option value="0">Manual only</option><option value="15">15 seconds</option><option value="30">30 seconds</option><option value="60">1 minute</option><option value="120">2 minutes</option><option value="300">5 minutes</option><option value="600">10 minutes</option></select></div></fieldset>
<fieldset><legend>On Exit</legend><div class="formgrid"><label>Monitors</label><select id="exit" class="mediumInput"><option>Disconnect</option><option>Keep</option><option>Uninstall</option></select><label>Restore Services</label><div class="checkboxCell"><input id="restore" type="checkbox"></div></div></fieldset>
<div class="actions"><button id="save" class="primary" type="submit">Save</button><button id="reset" type="button">Reset</button><button id="cancel" type="button">Cancel</button></div></form></div>
<script>
const q=i=>document.getElementById(i);let original;function fill(o){['vmu','web','socket'].forEach(k=>{q(k+'Interface').value=o[k].interface;q(k+'Port').value=o[k].port});q('retention').value=Math.ceil(o.logging.retentionMinutes/1440);q('preview').value=o.webUi.monitorPreviewRefreshSeconds;q('exit').value=o.exit.monitorAction;q('restore').checked=o.exit.restoreServices;dependency();}async function load(){original=await fetch('/api/settings',{cache:'no-store'}).then(r=>r.json());fill(original);}function dependency(){const forced=q('vmuInterface').value==='any';if(forced)q('webInterface').value='any';q('webInterface').disabled=forced;q('webInterface').title=forced?'VMU Server uses All Interfaces, therefore Web Server must also use All Interfaces.':'';}q('vmuInterface').addEventListener('change',dependency);q('reset').onclick=()=>fill(original);q('cancel').onclick=()=>location.href='/';q('form').onsubmit=async e=>{e.preventDefault();dependency();const x={vmu:{interface:q('vmuInterface').value,port:+q('vmuPort').value},web:{interface:q('webInterface').value,port:+q('webPort').value},socket:{interface:q('socketInterface').value,port:+q('socketPort').value},logging:{retentionMinutes:+q('retention').value*1440},webUi:{monitorPreviewRefreshSeconds:+q('preview').value},exit:{monitorAction:q('exit').value,restoreServices:q('restore').checked},serviceState:original.serviceState};const r=await fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});if(!r.ok){q('error').textContent=(await r.json()).error;return;}const result=await r.json();if(result.restartRequired)location.href=result.targetUrl;else location.reload();};load();
</script>
""";

    public static string ArrangementBody() => """
<div class="arrangementPage"><div id="arr" class="arrangementWorkspace" aria-label="Display arrangement"></div><div class="arrangementActions"><label class="snapToggle"><input id="snap" type="checkbox" checked> Snap to monitors</label><button id="apply" class="primary" type="button" disabled>Apply</button><button id="reset" type="button">Reset</button></div></div>
<div id="keepDialog" class="modal hidden"><div class="modalCard"><h2>Keep these display settings?</h2><p>Reverting in <strong id="countdown">15</strong> seconds.</p><div class="actions"><button id="keep" class="primary" type="button">Keep changes</button><button id="revert" type="button">Revert</button></div></div></div>
<div id="externalChange" class="externalChange hidden">Display arrangement changed in Windows. <button id="reloadArrangement" type="button">Reload</button></div>
<script>
const arr=document.getElementById('arr'),apply=document.getElementById('apply'),reset=document.getElementById('reset'),snapToggle=document.getElementById('snap'),dialog=document.getElementById('keepDialog'),countdown=document.getElementById('countdown'),external=document.getElementById('externalChange');let displays=[],baseline='',scale=1,dirty=false,timer=null,serverSignature='';
function signature(a){return JSON.stringify(a.map(x=>[x.deviceName,x.x,x.y,x.width,x.height]).sort((a,b)=>a[0].localeCompare(b[0])));}function updateDirty(){dirty=signature(displays)!==baseline;apply.disabled=!dirty||!external.classList.contains('hidden');}function bounds(){return {minX:Math.min(...displays.map(x=>x.x)),minY:Math.min(...displays.map(x=>x.y)),maxX:Math.max(...displays.map(x=>x.x+x.width)),maxY:Math.max(...displays.map(x=>x.y+x.height))};}
function render(){if(!displays.length){arr.innerHTML='';return;}const b=bounds(),pad=40,w=Math.max(1,arr.clientWidth-pad*2),h=Math.max(1,arr.clientHeight-pad*2);scale=Math.min(w/Math.max(1,b.maxX-b.minX),h/Math.max(1,b.maxY-b.minY),1);const usedW=(b.maxX-b.minX)*scale,usedH=(b.maxY-b.minY)*scale,ox=(arr.clientWidth-usedW)/2,oy=(arr.clientHeight-usedH)/2;arr.innerHTML=displays.map((x,i)=>'<div class="arrdisplay '+(x.isVirtual?'virtual':'physical')+'" data-i="'+i+'" style="left:'+(ox+(x.x-b.minX)*scale)+'px;top:'+(oy+(x.y-b.minY)*scale)+'px;width:'+Math.max(90,x.width*scale)+'px;height:'+Math.max(60,x.height*scale)+'px"><strong>'+x.windowsNumber+'</strong>'+(x.title?'<span>'+x.title+'</span>':'')+'<i class="blockedMark">⊘</i></div>').join('');wire();updateDirty();}
function snap(i,nx,ny){if(!snapToggle.checked)return[Math.round(nx),Math.round(ny)];const d=displays[i],threshold=5;for(let j=0;j<displays.length;j++){if(j===i)continue;const o=displays[j],cx=[[nx,o.x+o.width],[nx+d.width,o.x],[nx,o.x],[nx+d.width,o.x+o.width]],cy=[[ny,o.y+o.height],[ny+d.height,o.y],[ny,o.y],[ny+d.height,o.y+o.height]];for(const [a,b] of cx)if(Math.abs(a-b)<=threshold){nx+=b-a;break;}for(const [a,b] of cy)if(Math.abs(a-b)<=threshold){ny+=b-a;break;}}return[Math.round(nx),Math.round(ny)];}
function wire(){arr.querySelectorAll('.arrdisplay').forEach(el=>{let start=null,lastTap=0;el.onpointerdown=e=>{el.setPointerCapture(e.pointerId);const i=+el.dataset.i;start={i,x:e.clientX,y:e.clientY,ox:displays[i].x,oy:displays[i].y,moved:false};el.classList.add('dragging');};el.onpointermove=e=>{if(!start)return;const dx=(e.clientX-start.x)/scale,dy=(e.clientY-start.y)/scale;if(Math.abs(dx)+Math.abs(dy)>2)start.moved=true;const p=snap(start.i,start.ox+dx,start.oy+dy);displays[start.i].x=p[0];displays[start.i].y=p[1];render();};el.onpointerup=e=>{const was=start;start=null;el.classList.remove('dragging');if(was&&!was.moved){const now=Date.now();if(now-lastTap<360)openDisplay(+el.dataset.i,el);lastTap=now;}};el.ondblclick=e=>{e.preventDefault();openDisplay(+el.dataset.i,el);};});}
async function openDisplay(i,el){const d=displays[i];if(d.isVirtual&&d.monitorName){location.href='/monitors/'+encodeURIComponent(d.monitorName);return;}const r=await fetch('/api/arrangement/open-windows-settings',{method:'POST'});if(!r.ok){el.classList.add('blocked');setTimeout(()=>el.classList.remove('blocked'),900);}}
async function load(){displays=await fetch('/api/arrangement',{cache:'no-store'}).then(r=>r.json());baseline=signature(displays);serverSignature=baseline;external.classList.add('hidden');render();}
async function watchWindows(){if(!dialog.classList.contains('hidden'))return;try{const latest=await fetch('/api/arrangement',{cache:'no-store'}).then(r=>r.json()),sig=signature(latest);if(sig===serverSignature)return;if(dirty){external.classList.remove('hidden');apply.disabled=true;}else{displays=latest;baseline=sig;serverSignature=sig;render();}}catch{}}
apply.onclick=async()=>{if(!dirty||!external.classList.contains('hidden'))return;const r=await fetch('/api/arrangement/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({displays:displays.map(x=>({deviceName:x.deviceName,x:x.x,y:x.y}))})});if(!r.ok){alert((await r.json()).error);return;}const x=await r.json();showConfirm(x.confirmSeconds||15);};reset.onclick=load;document.getElementById('reloadArrangement').onclick=load;
function showConfirm(seconds){dialog.classList.remove('hidden');let remain=seconds;countdown.textContent=remain;clearInterval(timer);timer=setInterval(()=>{remain--;countdown.textContent=Math.max(0,remain);if(remain<=0){clearInterval(timer);dialog.classList.add('hidden');setTimeout(load,400);}},1000);}document.getElementById('keep').onclick=async()=>{await fetch('/api/arrangement/keep',{method:'POST'});clearInterval(timer);dialog.classList.add('hidden');await load();};document.getElementById('revert').onclick=async()=>{await fetch('/api/arrangement/revert',{method:'POST'});clearInterval(timer);dialog.classList.add('hidden');setTimeout(load,300);};window.addEventListener('resize',render);load();setInterval(watchWindows,1500);
</script>
""";

    public static string MonitorsBody(int intervalSeconds) => """
<div class="page"><h1>Monitors</h1><div id="grid" class="monitorgrid"></div></div><script>
const interval=__INTERVAL__,g=document.getElementById('grid');async function load(){const a=await fetch('/api/monitors',{cache:'no-store'}).then(r=>r.json());g.innerHTML=a.map(m=>'<div class="monitorcard" data-id="'+m.configuration.vmuId+'"><div class="cardtools"><button class="iconButton move" type="button" aria-label="Move monitor" title="Drag to reorder">⠿</button><button class="iconButton refresh" type="button" aria-label="Refresh preview" title="Refresh preview" '+(m.connected?'':'disabled')+'>↻</button></div><a href="/monitors/'+encodeURIComponent(m.configuration.name)+'"><div class="monitorpic"><img class="preview '+(m.connected?'':'hidden')+'" src="'+(m.connected?'/api/monitors/'+encodeURIComponent(m.configuration.name)+'/thumbnail?t='+Date.now():'')+'"><div class="screen '+(m.connected?'hidden':'')+'"></div><div class="stand"></div></div><h3><span class="avatarSlot">'+avatarHtml(m)+'</span><span>'+escapeHtml(m.configuration.title)+'</span></h3><div>'+m.width+' × '+m.height+'</div><div><span class="dot '+(m.connected?'on':'off')+'"></span> '+(m.connected?'On':'Off')+'</div></a></div>').join('')+'<a class="monitorcard addmonitor" href="/monitors/new"><div class="plus">＋</div><h3>Add Monitor</h3></a>';wire();}function escapeHtml(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML;}function avatarHtml(m){return m.configuration.avatarKind==='custom'?'<img class="cardAvatar" src="/api/monitors/'+encodeURIComponent(m.configuration.name)+'/avatar?t='+Date.now()+'">':'<span class="avatarEmoji">'+window.vmuAnimalEmoji(m.configuration.avatarValue)+'</span>';}
function refreshCard(button){if(button.disabled)return;const card=button.closest('.monitorcard'),img=card.querySelector('.preview');if(!img||img.classList.contains('hidden'))return;button.classList.add('spinning');button.disabled=true;card.classList.add('refreshing');const done=()=>{button.classList.remove('spinning');button.disabled=false;card.classList.remove('refreshing');img.removeEventListener('load',done);img.removeEventListener('error',done);};img.addEventListener('load',done);img.addEventListener('error',done);img.src=img.src.split('?')[0]+'?force=1&t='+Date.now();}
async function saveOrder(){await fetch('/api/monitors/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[...document.querySelectorAll('.monitorcard[data-id]')].map(x=>x.dataset.id)})});}
function wire(){document.querySelectorAll('.refresh').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();refreshCard(b);});document.querySelectorAll('.move').forEach(handle=>{let card=null,pointer=null,ghost=null,dx=0,dy=0;handle.onpointerdown=e=>{e.preventDefault();e.stopPropagation();card=handle.closest('.monitorcard');pointer=e.pointerId;handle.setPointerCapture(pointer);const r=card.getBoundingClientRect();dx=e.clientX-r.left;dy=e.clientY-r.top;ghost=card.cloneNode(true);ghost.classList.add('dragGhost');ghost.style.width=r.width+'px';ghost.style.height=r.height+'px';document.body.appendChild(ghost);ghost.style.left=(e.clientX-dx)+'px';ghost.style.top=(e.clientY-dy)+'px';card.classList.add('dragSource');};handle.onpointermove=e=>{if(!card||e.pointerId!==pointer)return;ghost.style.left=(e.clientX-dx)+'px';ghost.style.top=(e.clientY-dy)+'px';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.monitorcard[data-id]');if(target&&target!==card){const r=target.getBoundingClientRect();g.insertBefore(card,e.clientY<r.top+r.height/2?target:target.nextSibling);}};const finish=async()=>{if(!card)return;card.classList.remove('dragSource');ghost?.remove();card=null;ghost=null;pointer=null;await saveOrder();};handle.onpointerup=e=>{if(e.pointerId===pointer)finish();};handle.onpointercancel=finish;});}
function previews(){if(document.hidden||interval===0)return;document.querySelectorAll('.preview:not(.hidden)').forEach(i=>{i.src=i.src.split('?')[0]+'?t='+Date.now();});}load();if(interval>0)setInterval(previews,interval*1000);
</script>
""".Replace("__INTERVAL__", intervalSeconds.ToString(System.Globalization.CultureInfo.InvariantCulture));

    public static string AvatarPicker(string kind, string value, string? monitorName = null)
    {
        var animal = kind.Equals("animal", StringComparison.OrdinalIgnoreCase) ? value : MonitorAvatarService.RandomAnimal();
        var animalButtons = string.Join("", MonitorAvatarService.AnimalNames.Select(name => $"<button type=\"button\" data-animal=\"{WebUtility.HtmlEncode(name)}\">{MonitorAvatarService.GetEmoji("animal", name)}</button>"));
        var custom = kind.Equals("custom", StringComparison.OrdinalIgnoreCase) && monitorName is not null ? $"<button type=\"button\" class=\"customtile selected\" data-custom=\"1\"><img src=\"/api/monitors/{Uri.EscapeDataString(monitorName)}/avatar?t={DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}\" alt=\"Custom avatar\"></button>" : string.Empty;
        var current = kind.Equals("custom", StringComparison.OrdinalIgnoreCase) && monitorName is not null ? $"<img src=\"/api/monitors/{Uri.EscapeDataString(monitorName)}/avatar?t={DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}\" alt=\"Custom avatar\">" : MonitorAvatarService.GetEmoji("animal", animal);
        return $"<div class=\"avatarpicker\" data-kind=\"{WebUtility.HtmlEncode(kind)}\" data-selected=\"{WebUtility.HtmlEncode(animal)}\"><button type=\"button\" class=\"avatarcurrent\">{current}</button><div class=\"avatargrid hidden\">{animalButtons}{custom}<button type=\"button\" class=\"avataradd\" aria-label=\"Add custom avatar\" title=\"Add custom avatar\">＋</button></div><input class=\"avatarfile\" type=\"file\" accept=\".png,.ico,.gif\" hidden></div>";
    }

    public static string AvatarPickerJs => """
function picker(){const p=document.querySelector('.avatarpicker'),cur=p.querySelector('.avatarcurrent'),grid=p.querySelector('.avatargrid'),file=p.querySelector('.avatarfile'),add=p.querySelector('.avataradd');function changed(){p.dispatchEvent(new Event('avatar-changed',{bubbles:true}));}function selectAnimal(a){p.dataset.kind='animal';p.dataset.selected=a;p._file=null;grid.querySelectorAll('[data-animal]').forEach(x=>x.classList.toggle('selected',x.dataset.animal===a));grid.querySelectorAll('.customtile').forEach(x=>x.classList.remove('selected'));cur.innerHTML=window.vmuAnimalEmoji(a);changed();}cur.onclick=()=>grid.classList.toggle('hidden');grid.querySelectorAll('[data-animal]').forEach(b=>b.onclick=()=>{selectAnimal(b.dataset.animal);grid.classList.add('hidden')});const existing=grid.querySelector('.customtile');if(existing)existing.onclick=()=>{p.dataset.kind='custom';p._file=null;grid.querySelectorAll('[data-animal]').forEach(x=>x.classList.remove('selected'));existing.classList.add('selected');cur.innerHTML=existing.innerHTML;grid.classList.add('hidden');changed();};add.onclick=()=>file.click();file.onchange=()=>{if(!file.files[0])return;p.dataset.kind='custom';p._file=file.files[0];grid.querySelectorAll('[data-animal],.customtile').forEach(x=>x.classList.remove('selected'));let tile=grid.querySelector('.customupload');if(!tile){tile=document.createElement('button');tile.type='button';tile.className='customtile customupload selected';tile.innerHTML='<img alt="Custom avatar">';grid.insertBefore(tile,add);}tile.classList.add('selected');const url=URL.createObjectURL(p._file);tile.querySelector('img').src=url;cur.innerHTML='<img src="'+url+'" alt="Custom avatar">';grid.classList.add('hidden');changed();};if(p.dataset.kind==='animal')grid.querySelectorAll('[data-animal]').forEach(x=>x.classList.toggle('selected',x.dataset.animal===p.dataset.selected));}setTimeout(picker,0);
""";

    public static string NewMonitorBody(string picker, string rates) => """
