    public static string MonitorPropertiesBody(string monitorName, string picker, string rates) => """
<div class="page"><h1>Monitor Properties</h1><div id="error" class="error"></div><form id="f" class="properties"><label>Title <input id="title"></label><label>Name <input id="name"></label><label>Avatar __PICKER__</label><label>Resolution <select id="res"><option>1280x720</option><option>1920x1080</option><option>2560x1440</option><option>3840x2160</option></select></label><label>Refresh Rate <select id="hz">__RATES__</select></label><label>Orientation <select id="portrait"><option value="false">Landscape</option><option value="true">Portrait</option></select></label>
<fieldset><legend>Remote Access</legend><label>Mode <select id="remote"><option>Disabled</option><option>Presentation</option><option>Collaboration</option></select></label><div id="caps"><label><input id="clip" type="checkbox"> Clipboard</label><label><input id="mouse" type="checkbox"> Mouse</label><label><input id="key" type="checkbox"> Keyboard</label></div><label>Access <select id="security"><option>Public</option><option>Password</option><option value="ApiKey">API Key</option><option value="Approval">White/Black List Approval</option></select></label><label>Password <input id="password" type="password"></label><label>API Key <input id="api" readonly></label></fieldset>
<fieldset><legend>Windows Settings</legend><label>Windows Display <input id="wd" readonly></label><label>GDI <input id="gdi" readonly></label><label>Current Position <span class="inlineField"><input id="pos" readonly><a class="buttonlink" href="/arrangement">Arrange</a></span></label></fieldset>
<fieldset><legend>Monitor Health</legend><div class="health"><strong id="hs"></strong><span id="ht"></span><p id="hm"></p></div></fieldset><div class="actions propertyActions"><div class="actionLeft"><button id="save" class="primary" disabled>Save</button><a class="buttonlink" href="/monitors">Cancel</a><button type="button" id="connect">Connect</button><button type="button" id="disconnect">Disconnect</button><a class="buttonlink positive" id="terminal">Open Terminal</a></div><button type="button" id="uninstall" class="danger">Uninstall</button></div></form></div>
<script>__PICKERJS__const id=__ID__,q=i=>document.getElementById(i);let m,base='';function state(){const p=document.querySelector('.avatarpicker');return JSON.stringify([q('title').value,q('name').value,q('res').value,q('hz').value,q('portrait').value,q('remote').value,q('security').value,q('clip').checked,q('mouse').checked,q('key').checked,p.dataset.kind,p.dataset.selected,!!p._file]);}function dirty(){q('save').disabled=state()===base;}async function load(){m=await fetch('/api/monitors/'+encodeURIComponent(id),{cache:'no-store'}).then(r=>r.json());q('title').value=m.configuration.title;q('name').value=m.configuration.name;q('res').value=m.configuration.width+'x'+m.configuration.height;q('hz').value=m.configuration.refreshRate;q('portrait').value=String(m.configuration.portrait);q('wd').value=m.windowsDisplay??'—';q('gdi').value=m.deviceName??'—';q('pos').value=m.positionX==null?'—':'X: '+m.positionX+', Y: '+m.positionY;q('hs').textContent=m.health.state;q('hs').className=m.health.isError?'bad':'good';q('hm').textContent=m.health.message;q('ht').textContent=m.health.timestamp?new Date(m.health.timestamp).toLocaleString():'';q('remote').value=m.configuration.remoteAccess;q('security').value=m.configuration.securityMode;q('api').value=m.configuration.apiKey||'';q('clip').checked=m.configuration.collaborationClipboard;q('mouse').checked=m.configuration.collaborationMouse;q('key').checked=m.configuration.collaborationKeyboard;q('connect').disabled=!m.installed||m.connected;q('disconnect').disabled=!m.connected;q('uninstall').disabled=m.connected;const s=await fetch('/api/status',{cache:'no-store'}).then(r=>r.json());const vr=s.services.find(x=>x.key==='VMU_SERVER')?.running===true;q('terminal').classList.toggle('disabledLink',!vr||!m.connected||m.health.isError);q('terminal').href=vr&&m.connected&&!m.health.isError?'/monitor/'+encodeURIComponent(m.configuration.name):'#';base=state();dirty();}q('f').addEventListener('input',dirty);q('f').addEventListener('change',dirty);q('f').addEventListener('avatar-changed',dirty);q('f').onsubmit=async e=>{e.preventDefault();if(q('save').disabled)return;const wh=q('res').value.split('x').map(Number),x={title:q('title').value,name:q('name').value,width:wh[0],height:wh[1],refreshRate:+q('hz').value,portrait:q('portrait').value==='true',remoteAccess:q('remote').value,securityMode:q('security').value,password:q('password').value||null,regenerateApiKey:false,collaborationClipboard:q('clip').checked,collaborationMouse:q('mouse').checked,collaborationKeyboard:q('key').checked},r=await fetch('/api/monitors/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});if(!r.ok){q('error').textContent=(await r.json()).error;return;}const u=await r.json(),p=document.querySelector('.avatarpicker');if(p._file){const fd=new FormData();fd.append('file',p._file);const ar=await fetch('/api/monitors/'+encodeURIComponent(u.configuration.name)+'/avatar/upload',{method:'POST',body:fd});if(!ar.ok){q('error').textContent=(await ar.json()).error;return;}}else if(p.dataset.kind==='animal')await fetch('/api/monitors/'+encodeURIComponent(u.configuration.name)+'/avatar/animal/'+encodeURIComponent(p.dataset.selected),{method:'POST'});location.href='/monitors/'+encodeURIComponent(u.configuration.name);};async function act(a){const r=await fetch('/api/monitors/'+encodeURIComponent(id)+'/'+a,{method:'POST'});if(!r.ok)alert((await r.json()).error);else{await load();await window.vmuRefreshMonitorNav?.();}}q('connect').onclick=()=>act('connect');q('disconnect').onclick=()=>act('disconnect');q('uninstall').onclick=async()=>{if(q('uninstall').disabled)return;if(!confirm('Are you sure you want to uninstall this monitor?'))return;const r=await fetch('/api/monitors/'+encodeURIComponent(id)+'/uninstall',{method:'POST'});if(!r.ok){alert((await r.json()).error);return;}location.href='/monitors';};load();</script>
""".Replace("__PICKER__", picker).Replace("__RATES__", rates).Replace("__PICKERJS__", AvatarPickerJs).Replace("__ID__", JsonSerializer.Serialize(monitorName));

    public static string TerminalBody(string monitorName, bool connectedAndHealthy, bool vmuRunning) => """
<div class="terminalPage"><div id="terminalStopped" class="terminalStopped __STOPPED__"><div><h2>VMU Server is stopped</h2><p>Terminal is unavailable while the VMU Server is stopped.</p><a class="buttonlink primary" href="/settings">Open Settings</a></div></div><div id="terminalUnavailable" class="terminalStopped __UNAVAILABLE__"><div><h2>Terminal is unavailable</h2><p>This monitor must be connected and healthy before Terminal can be opened.</p><a class="buttonlink" href="/monitors/__NAME__">Open Properties</a></div></div><img id="live" class="terminalImage __IMAGE__" data-src="/api/monitors/__NAME__/live" alt="Virtual monitor live view"></div><script>
const live=document.getElementById('live'),stopped=document.getElementById('terminalStopped'),unavailable=document.getElementById('terminalUnavailable');let streamOn=false,restartTimer=null;function startStream(){if(streamOn)return;clearTimeout(restartTimer);live.src=live.dataset.src+'?t='+Date.now();streamOn=true;}function stopStream(){clearTimeout(restartTimer);live.removeAttribute('src');streamOn=false;}live.addEventListener('error',()=>{streamOn=false;restartTimer=setTimeout(terminalState,350);});async function terminalState(){try{const [s,m]=await Promise.all([fetch('/api/status',{cache:'no-store'}).then(r=>r.json()),fetch('/api/monitors/__NAME__',{cache:'no-store'}).then(r=>r.json())]);const vr=s.services.find(x=>x.key==='VMU_SERVER')?.running===true,ready=m.connected&&!m.health.isError;stopped.classList.toggle('hidden',vr);unavailable.classList.toggle('hidden',!vr||ready);live.classList.toggle('hidden',!vr||!ready);if(vr&&ready)startStream();else stopStream();}catch{}}setInterval(terminalState,1000);terminalState();
</script>
""".Replace("__NAME__", Uri.EscapeDataString(monitorName)).Replace("__STOPPED__", vmuRunning ? "hidden" : string.Empty).Replace("__UNAVAILABLE__", connectedAndHealthy || !vmuRunning ? "hidden" : string.Empty).Replace("__IMAGE__", vmuRunning && connectedAndHealthy ? string.Empty : "hidden");

