<div class="logpage"><div class="filters"><h3>Filters</h3><label><input type="checkbox" data-s="VMU" checked> VMU</label><label><input type="checkbox" data-s="VMU_SERVER" checked> VMU Server</label><label><input type="checkbox" data-s="WEB" checked> Web Server</label><label><input type="checkbox" data-s="SOCKET" checked> Socket Server</label></div><div class="logmain"><div class="toolbar"><input id="search" placeholder="Search..."></div><div class="tablewrap"><table id="log"><thead><tr><th>Timecode</th><th>Level</th><th>Service</th><th>Monitor</th><th>Event</th><th>Message</th></tr></thead><tbody></tbody></table></div><div class="logfooter"><label><input id="tail" type="checkbox" checked> Always at end</label><span id="count"></span><div class="logActions"><button onclick="exp('xlsx')">Export XLSX</button><button onclick="exp('csv')">Export CSV</button><button onclick="exp('txt')">Export TXT</button><button id="clear" class="danger">Clear</button></div></div></div></div><script>const q=i=>document.getElementById(i),tb=document.querySelector('#log tbody');function query(){const p=new URLSearchParams();document.querySelectorAll('[data-s]:checked').forEach(x=>p.append('service',x.dataset.s));if(q('search').value)p.set('q',q('search').value);return p;}async function refresh(){const p=query(),a=await Promise.all([fetch('/api/log?'+p).then(r=>r.json()),fetch('/api/log/count?'+p).then(r=>r.json())]),rows=a[0],c=a[1];tb.innerHTML=rows.map(x=>'<tr><td>'+new Date(x.timestamp).toLocaleString()+'</td><td>'+x.level+'</td><td>'+x.service+'</td><td>'+(x.monitorId||'')+'</td><td>'+x.event+'</td><td>'+x.message+'</td></tr>').join('');const filtered=q('search').value||document.querySelectorAll('[data-s]:not(:checked)').length;q('count').innerHTML=filtered?'Displayed <b>'+c.filtered+'</b> of <b>'+c.total+'</b> records.':'Total records <b>'+c.total+'</b>';if(q('tail').checked&&tb.lastElementChild)tb.lastElementChild.scrollIntoView({block:'nearest'});}document.querySelectorAll('[data-s]').forEach(x=>x.onchange=refresh);q('search').oninput=refresh;q('clear').onclick=async()=>{if(confirm('Clear log?')){await fetch('/api/log',{method:'DELETE'});refresh();}};function exp(f){location.href='/api/log/export/'+f+'?'+query();}refresh();setInterval(refresh,1000);</script>
